public class SerialPortManager { @Resource private SerialPortFactory factory; //串口名称与串口的map private final ConcurrentHashMap<String, SerialPortBase<?>> serialPortMap = new ConcurrentHashMap<>(); @PostConstruct private void init() { for (SerialPort commPort : SerialPort.getCommPorts()) { SerialPortHandler<Object> handler = factory.getSerialPortHandler(SerialPortEnum.getEnum(commPort.getSystemPortName())); if (handler == null) { log.error("系统无可用串口，初始化结束"); return; } serialPortMap.put(commPort.getSystemPortName(), initializeSerialPortBase(commPort, handler.dataParser(), handler.dataService())); commPort.openPort(); commPort.setComPortParameters(9600, 8, 1, 0, true); commPort.setComPortTimeouts(SerialPort.TIMEOUT_READ_SEMI_BLOCKING, 1000, 0); log.info("串口初始化,systemPortName:{},descriptivePortName:{},portDescription:{},portLocation:{}" , commPort.getSystemPortName(), commPort.getDescriptivePortName(), commPort.getPortDescription(), commPort.getPortLocation()); } } private static <T> SerialPortBase<T> initializeSerialPortBase(SerialPort commPort, DataParser<T> parser, DataService<T> dataService) { return new SerialPortBase<>(commPort, parser, dataService); } // 通过串口名称获取串口管理对象 public SerialPortBase<?> getSerialPortBase(String portName) { return serialPortMap.get(portName); } } @AllArgsConstructor @NoArgsConstructor @Data @Slf4j public class SerialPortBase<T> { private SerialPort serialPort; private SerialPortSend send; private SerialPortReceive receive; private CommandQueue commandQueue; private DataParser<T> parser; private DataService<T> service; private ScheduledExecutorService scheduler; private boolean unRead = false; private int retryTimes = 0; public SerialPortBase(SerialPort serialPort, DataParser<T> parser, DataService<T> service) { this.serialPort = serialPort; this.parser = parser; this.service = service; send = new SerialPortSend(serialPort); receive = new SerialPortReceive(); commandQueue = new CommandQueue(); unRead = false; retryTimes = 0; setListener(); System.out.println("串口设置完成"); startRetryTimer(); } /** * 设置监听器 */ private void setListener() { serialPort.addDataListener(new SerialPortDataListener() { @Override public int getListeningEvents() { return SerialPort.LISTENING_EVENT_DATA_AVAILABLE; } @Override public void serialEvent(SerialPortEvent serialPortEvent) { if (serialPortEvent.getEventType() == SerialPort.LISTENING_EVENT_DATA_AVAILABLE) { //可读并且收到完整帧 if (unRead && receiveComplete()) { BaseBaud out = out(); T parse = parser.parse(HexUtil.hexToBytes(out.getData())); System.out.print(serialPort.getSystemPortName() + ": "); parser.print(parse); service.save(out.getAddress(), parse); clean(); //完成后发送下一条数据 send(); } } } }); } /** * 读取串口缓冲区内数据到接收缓冲区 * * @return 接收缓冲区是否读完一帧数据 */ private boolean receiveComplete() { return receive.receive(serialPort); } /** * 发送指令 */ public void send() { String command = commandQueue.consumeCommand(); if (command != null) { System.out.println("剩余指令数量：" + commandQueue.size() + "重试次数" + retryTimes + "发送指令:" + command); setUnRead(send.sendCommand(command)); } retryTimes = 0; } public boolean openPort() { return serialPort.openPort(); } public boolean closePort() { return serialPort.closePort(); } /** * 启动重试定时器 */ public void startRetryTimer() { scheduler = Executors.newSingleThreadScheduledExecutor(); scheduler.scheduleAtFixedRate(() -> { log.info("
监听==========================
unread：{}
retryTimes:{}
buffer:{}
剩余指令数:{}

", unRead, retryTimes, receive.getBuffer(), commandQueue.size()); if (unRead) { retryTimes++; if (retryTimes > 2) { service.saveEmpty(send.getAddress()); clean(); send(); } } }, 0, 500, TimeUnit.MILLISECONDS); } /** * 停止重试定时器 */ public void stopRetryTimer() { if (scheduler != null) { scheduler.shutdown(); retryTimes = 0; } } private BaseBaud out() { byte[] buffer = receive.getBuffer(); byte[] cleanBuffer = receive.getCleanBuffer(); try { return new BaseBaud(buffer); } catch (RuntimeException e) { serialPort.readBytes(cleanBuffer, cleanBuffer.length); throw e; } finally { receive.clean(); } } private void clean() { receive.clean(); unRead = false; retryTimes = 0; } } 请你帮我分析这两个类的架构和作用，并给出改进意见，例如代码设计，命名规范等

