f.current_form_index = 0 if not self.form_data_list: self.feedback_form = FeedbackForm(self) self.central_widget.addWidget(self.feedback_form) self.central_widget.setCurrentWidget(self.feedback_form) else: self.load_feedback_form(self.form_data_list[self.current_form_index]) def add_new_feedback_form(self): self.save_current_form_data() new_feedback_form = FeedbackForm(self) self.central_widget.addWidget(new_feedback_form) self.central_widget.setCurrentWidget(new_feedback_form) self.current_form_index += 1 if self.current_form_index < len(self.form_data_list): self.form_data_list[self.current_form_index] = {} else: self.form_data_list.append({}) def save_current_form_data(self): current_feedback_form = self.central_widget.currentWidget() if isinstance(current_feedback_form, FeedbackForm): data = current_feedback_form.get_data() if self.current_form_index < len(self.form_data_list): self.form_data_list[self.current_form_index] = data else: self.form_data_list.append(data) def load_feedback_form(self, data): feedback_form = FeedbackForm(self) feedback_form.set_data(data) self.central_widget.addWidget(feedback_form) self.central_widget.setCurrentWidget(feedback_form) def go_back_to_previous_form(self): if self.current_form_index > 0: self.save_current_form_data() self.current_form_index -= 1 previous_data = self.form_data_list[self.current_form_index] self.load_feedback_form(previous_data) def go_forward_to_next_form(self): if self.current_form_index < len(self.form_data_list) - 1: self.save_current_form_data() self.current_form_index += 1 next_data = self.form_data_list[self.current_form_index] self.load_feedback_form(next_data) def show_evaluation(self): self.save_current_form_data() self.evaluation_page.update_data(self.form_data_list) self.central_widget.setCurrentWidget(self.evaluation_page) def get_last_feedback_form(self): return self.current_form_index class WrapDelegate(QStyledItemDelegate): def createEditor(self, parent, option, index): editor = QTextEdit(parent) return editor def setEditorData(self, editor, index): editor.setText(index.data()) def setModelData(self, editor, model, index): model.setData(index, editor.toPlainText()) def updateEditorGeometry(self, editor, option, index): editor.setGeometry(option.rect) def sizeHint(self, option, index): return QSize(option.rect.width(), 100) class FeedbackForm(QMainWindow): def __init__(self, parent=None): super().__init__(parent) self.initUI() def get_main_window(self): parent = self.parent() while parent is not None: if isinstance(parent, MainWindow): return parent parent = parent.parent() return None def update_row_heights(self, row, column): if column == 1: self.feedback_table.resizeRowToContents(row) def initUI(self): self.setWindowTitle('Feedback Form') self.setGeometry(100, 100, 800, 1000) main_layout = QVBoxLayout() title_label = QLabel('Planspiel "Der Landtag sind wir!"', self) title_font = QFont() title_font.setPointSize(16) title_label.setFont(title_font) main_layout.addWidget(title_label) age_label = QLabel('Alter:', self) age_font = QFont() age_font.setPointSize(12) age_label.setFont(age_font) self.age_input = QLineEdit(self) self.age_input.setFixedWidth(50) age_layout = QHBoxLayout() age_layout.addWidget(age_label) age_layout.addWidget(self.age_input) age_layout.addStretch(1) main_layout.addLayout(age_layout) nationality_label = QLabel('Nationalitäten:', self) nationality_label.setFont(age_font) self.nationality_input = QComboBox(self) self.nationality_input.addItems([ "deutsch", "deutsch mit Migrationshintergrund", "nicht deutsch" ]) nationality_layout = QVBoxLayout() nationality_layout.addWidget(nationality_label) nationality_layout.addWidget(self.nationality_input) main_layout.addLayout(nationality_layout) gender_layout = QHBoxLayout() gender_label = QLabel('Geschlecht:', self) gender_label.setFont(age_font) self.gender_female = QRadioButton('weiblich', self) self.gender_male = QRadioButton('männlich', self) self.gender_diverse = QRadioButton('divers', self) self.gender_group = QButtonGroup(self) self.gender_group.addButton(self.gender_female) self.gender_group.addButton(self.gender_male) self.gender_group.addButton(self.gender_diverse) gender_layout.addWidget(gender_label) gender_layout.addWidget(self.gender_female) gender_layout.addWidget(self.gender_male) gender_layout.addWidget(self.gender_diverse) gender_layout.addStretch(1) main_layout.addLayout(gender_layout) party_layout = QHBoxLayout() party_label = QLabel('Partei:', self) party_label.setFont(age_font) self.party_conservative = QRadioButton('Die Konservativen', self) self.party_free = QRadioButton('Die Freien', self) self.party_green = QRadioButton('Die Ökologen', self) self.party_social = QRadioButton('Die Sozialien', self) self.party_press = QRadioButton('Presse', self) self.party_group = QButtonGroup(self) self.party_group.addButton(self.party_conservative) self.party_group.addButton(self.party_free) self.party_group.addButton(self.party_green) self.party_group.addButton(self.party_social) self.party_group.addButton(self.party_press) party_layout.addWidget(party_label) party_layout.addWidget(self.party_conservative) party_layout.addWidget(self.party_free) party_layout.addWidget(self.party_green) party_layout.addWidget(self.party_social) party_layout.addWidget(self.party_press) party_layout.addStretch(1) main_layout.addLayout(party_layout) self.feedback_table = QTableWidget(6, 2, self) self.feedback_table.setHorizontalHeaderLabels(['Schulnote (1-6)', 'Kommentare']) self.feedback_table.setVerticalHeaderLabels([ 'Zufriedenheit mit der heutigen Erfahrung', 'Planspielmaterialien', 'Einführung zum Planspiel', 'Betreuung während der Durchführung', 'Zeitplan und Ablauf', 'Vorbereitung in der Schule' ]) self.feedback_table.setColumnWidth(0, 150) self.feedback_table.setColumnWidth(1, 350) delegate = WrapDelegate(self.feedback_table) self.feedback_table.setItemDelegateForColumn(1, delegate) self.feedback_table.cellChanged.connect(self.update_row_heights) main_layout.addWidget(self.feedback_table) save_button = QPushButton('Speichern', self) next_button = QPushButton('Nächstes Formular', self) prev_button = QPushButton('Vorheriges Formular', self) evaluate_button = QPushButton('Auswerten', self) button_layout = QHBoxLayout() button_layout.addWidget(save_button) button_layout.addWidget(prev_button) button_layout.addWidget(next_button) button_layout.addWidget(evaluate_button) main_layout.addLayout(button_layout) container = QWidget() container.setLayout(main_layout) self.setCentralWidget(container) next_button.clicked.connect(self.get_main_window().add_new_feedback_form) prev_button.clicked.connect(self.get_main_window().go_back_to_previous_form) evaluate_button.clicked.connect(self.get_main_window().show_evaluation) def get_data(self): data = { 'age': self.age_input.text(), 'nationality': self.nationality_input.currentText(), 'gender': self.gender_group.checkedButton().text() if self.gender_group.checkedButton() else '', 'party': self.party_group.checkedButton().text() if self.party_group.checkedButton() else '', 'feedback': [] } for row in range(self.feedback_table.rowCount()): grade_item = self.feedback_table.item(row, 0) comment_item = self.feedback_table.item(row, 1) grade = grade_item.text() if grade_item else '' comment = comment_item.text() if comment_item else '' data['feedback'].append({'grade': grade, 'comment': comment}) return data def set_data(self, data): self.age_input.setText(data.get('age', '')) nationality = data.get('nationality', '') index = self.nationality_input.findText(nationality) if index >= 0: self.nationality_input.setCurrentIndex(index) gender = data.get('gender', '') for button in self.gender_group.buttons(): if button.text() == gender: button.setChecked(True) break party = data.get('party', '') for button in self.party_group.buttons(): if button.text() == party: button.setChecked(True) break feedback = data.get('feedback', []) for row, entry in enumerate(feedback): grade_item = QTableWidgetItem(entry.get('grade', '')) comment_item = QTableWidgetItem(entry.get('comment', '')) self.feedback_table.setItem(row, 0, grade_item) self.feedback_table.setItem(row, 1, comment_item) self.update_row_heights(row, 1) class EvaluationPage(QWidget): def __init__(self, parent=None): super().__init__(parent) self.initUI() def initUI(self): layout = QVBoxLayout() title_label = QLabel('Auswertung') title_font = QFont() title_font.setPointSize(24) title_label.setFont(title_font) layout.addWidget(title_label, alignment=Qt.AlignCenter) self.data_list = QListWidget() layout.addWidget(self.data_list) self.filter_group = QVBoxLayout() self.add_checkboxes() layout.addLayout(self.filter_group) button_layout = QHBoxLayout() save_button = QPushButton('Daten speichern', self) save_button.clicked.connect(self.save_data_to_file) button_layout.addWidget(save_button) load_button = QPushButton('Daten laden', self) load_button.clicked.connect(self.load_data_from_file) button_layout.addWidget(load_button) back_button = QPushButton('Zurück', self) back_button.clicked.connect(self.go_back) button_layout.addWidget(back_button) layout.addLayout(button_layout) self.result_area = QLabel(self) layout.addWidget(self.result_area) self.setLayout(layout) def add_checkboxes(self): self.gender_checkboxes = { "weiblich": QCheckBox("weiblich", self), "männlich": QCheckBox("männlich", self), "divers": QCheckBox("divers", self) } self.nationality_checkboxes = { "deutsch": QCheckBox("deutsch", self), "nicht deutsch": QCheckBox("nicht deutsch", self), "deutsch mit Migrationshintergrund": QCheckBox("deutsch mit Migrationshintergrund", self) } self.age_checkboxes = {str(age): QCheckBox(str(age), self) for age in range(10, 21)} self.filter_group.addWidget(QLabel("Geschlecht")) for cb in self.gender_checkboxes.values(): self.filter_group.addWidget(cb) self.filter_group.addWidget(QLabel("Nationalität")) for cb in self.nationality_checkboxes.values(): self.filter_group.addWidget(cb) self.filter_group.addWidget(QLabel("Alter")) for cb in self.age_checkboxes.values(): self.filter_group.addWidget(cb) for group in [self.gender_checkboxes, self.nationality_checkboxes, self.age_checkboxes]: for checkbox in group.values(): checkbox.stateChanged.connect(self.apply_filter) def update_data(self, form_data_list): self.form_data_list = form_data_list self.display_data() self.calculate_statistics() def display_data(self): self.data_list.clear() for data in self.form_data_list: display_text = f"Alter: {data['age']}, Nationalität: {data['nationality']}, " \ f"Geschlecht: {data['gender']}, Partei: {data['party']}" self.data_list.addItem(display_text) def apply_filter(self): self.display_data() self.calculate_statistics() def calculate_statistics(self): filtered_data = self.form_data_list selected_genders = [key for key, cb in self.gender_checkboxes.items() if cb.isChecked()] selected_nationalities = [key for key, cb in self.nationality_checkboxes.items() if cb.isChecked()] selected_ages = [key for key, cb in self.age_checkboxes.items() if cb.isChecked()] if not selected_genders: selected_genders = self.gender_checkboxes.keys() if not selected_nationalities: selected_nationalities = self.nationality_checkboxes.keys() if not selected_ages: selected_ages = self.age_checkboxes.keys() filtered_data = [d for d in filtered_data if d['gender'] in selected_genders] filtered_data = [d for d in filtered_data if d['nationality'] in selected_nationalities] filtered_data = [d for d in filtered_data if d['age'] in selected_ages] total_participants = len(filtered_data) male_count = sum(1 for d in filtered_data if d['gender'] == 'männlich') female_count = sum(1 for d in filtered_data if d['gender'] == 'weiblich') diverse_count = sum(1 for d in filtered_data if d['gender'] == 'divers') age_sum = sum(int(d['age']) for d in filtered_data if d['age'].isdigit()) average_age = age_sum / total_participants if total_participants else 0 nationality_counts = {key: sum(1 for d in filtered_data if d['nationality'] == key) for key in self.nationality_checkboxes.keys()} party_counts = {party: sum(1 for d in filtered_data if d['party'] == party) for party in ['Die Konservativen', 'Die Freien', 'Die Ökologen', 'Die Sozialien', 'Presse']} average_grades = {i: sum(float(d['feedback'][i]['grade']) for d in filtered_data if d['feedback'][i]['grade']) / total_participants if total_participants else 0 for i in range(6)} self.result_area.setText( f"Durchschnittsalter: {average_age:.2f}
" f"Anzahl Männer: {male_count}
" f"Anzahl Frauen: {female_count}
" f"Anzahl Divers: {diverse_count}
