" f"nicht deutsch: {nationality_counts['nicht deutsch']}
" ) def save_data_to_file(self): file_dialog = QFileDialog() file_path, _ = file_dialog.getSaveFileName(self, 'Daten speichern', '', 'JSON Files (*.json)') if file_path: with open(file_path, 'w') as file: json.dump(self.form_data_list, file) def load_data_from_file(self): file_dialog = QFileDialog() file_path, _ = file_dialog.getOpenFileName(self, 'Daten laden', '', 'JSON Files (*.json)') if file_path: with open(file_path, 'r') as file: self.form_data_list = json.load(file) self.display_data() self.calculate_statistics() def go_back(self): self.parent().setCurrentIndex(1) if __name__ == '__main__': app = QApplication(sys.argv) window = MainWindow() window.show() sys.exit(app.exec_())

